import enum

from geoalchemy2 import Geometry
from sqlalchemy import Column, ForeignKey, Index, Integer, LargeBinary, SmallInteger, String
from sqlalchemy.ext.declarative import declared_attr

from datafusion.database.db_settings import db_settings
from datafusion.database.models.base_class import Base


class Layer(enum.Enum):
    GAS = 0
    DISTRICT_HEATING = 1


class Map(Base):
    id = Column(Integer, primary_key=True)
    layer = Column(SmallInteger, ForeignKey("kiutlayer.id", ondelete="CASCADE"))
    # Alembic doesn't know about the autogenerated spatial_index.
    # Set it false here and create it in __table_args__ :(
    geom = Column(Geometry("Polygon", spatial_index=False, srid=db_settings.DB_SRID))  # type: ignore
    image = Column(LargeBinary)
    url = Column(String)
    terc = Column(String(7))
    import_id = Column(Integer, ForeignKey("import_metadata.id", ondelete="CASCADE"))

    @declared_attr
    def __table_args__(self) -> tuple[Index]:
        return (
            Index(
                f"idx_{self.__tablename__}_geom",
                "geom",
                postgresql_using="gist",
            ),
        )
